do $seed$
declare item jsonb; l public.lessons; terms jsonb; result jsonb; set_id uuid; ids jsonb; blocks jsonb; inline_words jsonb;
begin
 for item in select value from jsonb_array_elements($bank$[{"id":"af2fb3d2-bd76-4afd-aac5-a0c9eecb0802","video":"Z1qFlfqlS_E","terms":[{"term":"quantity","definition":"A measurable property, such as length or time."},{"term":"unit","definition":"An agreed reference used to express a measured quantity."},{"term":"precision","definition":"The level of detail supported by a measurement."},{"term":"significant figures","definition":"The digits reported in a measurement to communicate its supported precision."}]},{"id":"eaa95227-1bc7-41e8-af7c-192bdedc8303","video":"vf7X7mmJfsE","terms":[{"term":"kinematics","definition":"The description of motion using position, velocity, and acceleration."},{"term":"position","definition":"An object’s location relative to a chosen origin."},{"term":"velocity","definition":"The rate of change of position, including direction."},{"term":"acceleration","definition":"The rate of change of velocity. Speed, direction, or both can change."}]},{"id":"fc67d63d-a011-426b-b9f3-fd8f1ea7f501","video":"u0V8uJ5KTvo","terms":[{"term":"origin","definition":"The chosen zero position of a coordinate system."},{"term":"position","definition":"An object’s location relative to a chosen origin."},{"term":"displacement","definition":"Final position minus initial position; it includes direction."},{"term":"distance","definition":"The total length of the path traveled; it has no direction."},{"term":"vector","definition":"A quantity with both magnitude and direction."}]},{"id":"7456e6c4-fd01-455f-b0a2-e8e1a0f65304","video":"djR8sAAi740","terms":[{"term":"coordinate","definition":"A number giving position along one chosen axis."},{"term":"axis","definition":"A reference line with an origin, scale, and positive direction."},{"term":"component","definition":"The signed part of a vector along one axis."},{"term":"position vector","definition":"A vector from the origin to an object’s location."},{"term":"displacement","definition":"The change in position, found by subtracting initial from final coordinates on each axis."}]},{"id":"df1acb44-9f62-45cf-9270-1f1a2d413505","video":"FshpPgPAeWM","terms":[{"term":"scalar","definition":"A quantity described by a magnitude and unit, without direction."},{"term":"vector","definition":"A quantity with both magnitude and direction."},{"term":"magnitude","definition":"The nonnegative size of a quantity; for a vector, the length of its arrow on the chosen scale."},{"term":"position vector","definition":"A vector with its tail at the origin and its head at the object’s location."},{"term":"component","definition":"The signed part of a vector along one axis."}]},{"id":"c1f8c609-88ad-4d42-93ce-25ae2b0c8206","video":"maoz-9mGWyk","terms":[{"term":"positive direction","definition":"The direction chosen to correspond to increasing coordinates along an axis."},{"term":"negative position","definition":"A location on the negative side of the origin; it does not specify the direction of motion."},{"term":"magnitude","definition":"The nonnegative size of a quantity. In one dimension, a position’s magnitude is its absolute value."},{"term":"origin","definition":"The chosen zero position of a coordinate system."}]},{"id":"685abc3e-737c-4572-9be2-928f8fd7a707","video":"YViTBR_aygk","terms":[{"term":"elapsed time","definition":"The time interval between two events: final time minus initial time."},{"term":"rate of change","definition":"How much a quantity changes per unit of time."},{"term":"average velocity","definition":"Displacement divided by elapsed time, including direction."},{"term":"meters per second","definition":"A unit of velocity or speed that relates a length in meters to a time in seconds."}]},{"id":"f2770d7c-8494-4808-9ba2-fb463bd47508","video":"hj8usnvYrRo","terms":[{"term":"average velocity","definition":"Displacement divided by elapsed time, including direction."},{"term":"average speed","definition":"Total distance traveled divided by elapsed time."},{"term":"instantaneous velocity","definition":"Velocity at a particular instant; the slope of the tangent to a position–time graph."},{"term":"instantaneous speed","definition":"The magnitude of instantaneous velocity."},{"term":"secant","definition":"A line through two points on a curve; on a position–time graph its slope gives average velocity between those times."},{"term":"tangent","definition":"A line matching a curve’s local direction at a point; on a position–time graph its slope gives instantaneous velocity."}]}]$bank$::jsonb) loop
  select * into strict l from public.lessons where id=(item->>'id')::uuid for update;
  if l.content_blocks->>'presentation'<>'physics-path' or not exists(select 1 from jsonb_array_elements(l.content_blocks->'blocks') b where b->>'youtubeId'=item->>'video') then raise exception 'Video lesson changed: %',l.id;end if;
  if exists(select 1 from public.vocabulary_sets where lesson_id=l.id::text) then continue;end if;
  select coalesce(jsonb_agg(t),'[]'::jsonb) into inline_words from jsonb_array_elements(l.content_blocks->'blocks') b cross join lateral jsonb_array_elements(coalesce(b->'terms','[]'::jsonb)) t where b->>'type'='vocab';
  select jsonb_agg(jsonb_build_object('tier',3)||w||coalesce((select t from jsonb_array_elements(inline_words) t where lower(t->>'term')=lower(w->>'term') limit 1),'{}'::jsonb)) into terms from jsonb_array_elements(item->'terms') w;
  terms:=terms||(select coalesce(jsonb_agg(t),'[]'::jsonb) from jsonb_array_elements(inline_words) t where not exists(select 1 from jsonb_array_elements(item->'terms') w where lower(w->>'term')=lower(t->>'term')));
  result:=public.save_lesson_vocabulary(l.id,null,terms,l.published);set_id:=(result->>'setId')::uuid;
  select jsonb_agg(id order by order_index) into ids from public.vocabulary_terms where vocabulary_set_id=set_id and not archived;
  select jsonb_agg(case when b->>'type'='vocab' then b||jsonb_build_object('terms','[]'::jsonb,'termIds',ids,'vocabularySetId',set_id) else b end order by ord) into blocks from jsonb_array_elements(l.content_blocks->'blocks') with ordinality a(b,ord);
  if not exists(select 1 from jsonb_array_elements(blocks) b where b->>'type'='vocab') then blocks:=blocks||jsonb_build_array(jsonb_build_object('id','vocabulary-'||(item->>'video'),'type','vocab','terms','[]'::jsonb,'termIds',ids,'vocabularySetId',set_id,'referencePanel',true));end if;
  update public.lessons set content_blocks=jsonb_set(content_blocks,'{blocks}',blocks),updated_at=now() where id=l.id;
  insert into public.vocab_target_terms(target_id,term_id) select t.id,w.id from public.learning_targets t cross join public.vocabulary_terms w where t.program='physics' and t.domain='knowledge' and w.vocabulary_set_id=set_id and not w.archived and l.content_blocks->'learningPath'->'targetSlugs' ? t.slug on conflict do nothing;
 end loop;
end $seed$;
select l.id,l.title,s.id as set_id,s.published,(select count(*) from public.vocabulary_terms t where t.vocabulary_set_id=s.id and not t.archived) as words,(select count(distinct v.target_id) from public.vocab_target_terms v join public.vocabulary_terms t on t.id=v.term_id where t.vocabulary_set_id=s.id) as targets from public.lessons l join public.vocabulary_sets s on s.lesson_id=l.id::text where l.id in ('af2fb3d2-bd76-4afd-aac5-a0c9eecb0802','eaa95227-1bc7-41e8-af7c-192bdedc8303','fc67d63d-a011-426b-b9f3-fd8f1ea7f501','7456e6c4-fd01-455f-b0a2-e8e1a0f65304','df1acb44-9f62-45cf-9270-1f1a2d413505','c1f8c609-88ad-4d42-93ce-25ae2b0c8206','685abc3e-737c-4572-9be2-928f8fd7a707','f2770d7c-8494-4808-9ba2-fb463bd47508') order by l.lesson_number;